import{_ as t,o,c as i,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Mobile Studio & Agency Subscription Plans, SePay VietQR Checkout, AI Credit Caps & Invoice History","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/08-mobile-application/mobile-subscription-billing/spec.md","filePath":"feature/modules/08-mobile-application/mobile-subscription-billing/spec.md"}'),n={name:"feature/modules/08-mobile-application/mobile-subscription-billing/spec.md"};function r(c,e,d,s,l,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="mobile-studio-agency-subscription-plans-sepay-vietqr-checkout-ai-credit-caps-invoice-history" tabindex="-1">Mobile Studio &amp; Agency Subscription Plans, SePay VietQR Checkout, AI Credit Caps &amp; Invoice History <a class="header-anchor" href="#mobile-studio-agency-subscription-plans-sepay-vietqr-checkout-ai-credit-caps-invoice-history" aria-label="Permalink to &quot;Mobile Studio &amp; Agency Subscription Plans, SePay VietQR Checkout, AI Credit Caps &amp; Invoice History&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>mobile-subscription-billing</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>08-mobile-application</code> — BrandHub Mobile Application (Expo SDK 58 / React Native 0.88)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>mobile-subscription-billing</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/08-subscription-billing/README.html">3.9 Subscription &amp; Billing</a> (<code>3.9.1–3.9.6</code>) · <a href="./../../../srs/09-admin-functions/README.html">FR 3.10.10–3.10.14 Admin Billing/Revenue</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Provide full mobile visibility and execution for <strong>Personal Studio &amp; Business Agency Subscription Plans</strong> (<code>SubscriptionPlansScreen.tsx</code>), <strong>SePay VietQR Dynamic Checkout &amp; Countdown</strong> (<code>BillingModals.tsx</code> + <code>react-native-qrcode-svg</code>), <strong>Unified Agency Wallet &amp; Workspace AI Credit Governance</strong> (<code>AgencyCreditScreen.tsx</code>), and <strong>Invoice History &amp; Receipt Inspection</strong> (<code>InvoiceHistoryScreen.tsx</code>, <code>InvoiceDetailScreen.tsx</code>, plus <code>AdminInvoicesScreen.tsx</code> &amp; <code>AdminRevenueScreen.tsx</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an Agency or Personal Studio <code>Owner</code> on mobile, I want to compare <code>1 / 3 / 6 / 12</code>-month plans, generate or save a SePay VietQR code to complete bank-app transfer on the same phone, monitor live payment fulfillment, manage Workspace AI Credit caps, and inspect/download verified receipts.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Dual-Line Plan Catalog &amp; Upgrade Quote (<code>SubscriptionPlansScreen.tsx</code>, <code>studioPlans.test.ts</code>):</strong> Automatically displays <code>STUDIO_FREE / STUDIO_PLUS / STUDIO_PRO</code> for <code>PERSONAL</code> Studio companies and <code>BASIC / PLUS / ENTERPRISE</code> for <code>AGENCY</code> companies across <code>1 / 3 / 6 / 12</code>-month billing cycles, showing <code>BillingOverviewResourcesCard.tsx</code> resource utilization and exact mid-period upgrade quotes (enforcing <code>Upgrade Plan</code> only, zero downgrade).</li><li><strong>Mobile SePay VietQR Checkout (<code>BillingModals.tsx</code>):</strong> Creates/resumes idempotent <code>billing_orders</code>, renders crisp vector VietQR (<code>react-native-qrcode-svg</code>) + copyable bank account / exact transfer content (<code>provider_order_code</code>) + save-QR-to-gallery (<code>expo-media-library</code> for 1-phone banking app scan), live server-anchored <code>15-minute</code> <code>mm:ss</code> countdown, and live order fulfillment polling.</li><li><strong>Workspace AI Credit Balance, Top-Up &amp; Caps (<code>AgencyCreditScreen.tsx</code>):</strong> Displays <code>PLAN</code> + <code>PURCHASED</code> wallet balances, per-Workspace period usage (<code>workspaceLimit</code>, <code>workspaceUsed</code>, <code>workspaceHeld</code>), <code>Owner</code> Workspace cap editor (<code>null</code> unlimited vs <code>0</code> blocked with <code>expectedRevision</code>), read-only operation price catalog, and SePay credit top-up checkout.</li><li><strong>Cursor-Paginated Invoice History &amp; Admin Revenue (<code>InvoiceHistoryScreen.tsx</code>, <code>InvoiceDetailScreen.tsx</code>, <code>AdminInvoicesScreen.tsx</code>, <code>AdminRevenueScreen.tsx</code>):</strong> Lists orders with cursor pagination, shows order/payment/fulfillment detail + on-demand SePay API v2 lookup, and downloads verified <code>FULFILLED</code> PDF receipts.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>billing.*</code>, <code>subscription.*</code>, <code>credit.*</code>, <code>invoices.*</code> in <code>src/i18n/locales/en.json</code> &amp; <code>src/i18n/locales/vi/common.json</code> (<code>tr()</code>)) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> Parity with <code>/agency/:id/subscription</code>, <code>/agency/:id/credit</code>, <code>/agency/:id/invoices</code>, <code>/admin?view=revenue</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/billing/{SubscriptionPlansScreen,AgencyCreditScreen,InvoiceHistoryScreen,InvoiceDetailScreen}.tsx</code>, <code>src/components/billing/*</code>, <code>src/screens/admin/{AdminInvoicesScreen,AdminRevenueScreen,AdminCreditPricesScreen,AdminReportsScreen}.tsx</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/billing/plans?agencyId={id} &amp; /agencies/{id}/subscription &amp; /upgrade-quote</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>BillingPlanController</code> &amp; <code>BillingController</code> &lt;- <code>billingService.ts</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/billing/agencies/{id}/orders &amp; /credits/orders &amp; GET /orders/{orderId}</code></td><td style="text-align:left;">Bearer (<code>Owner</code>) + <code>Idempotency-Key</code></td><td style="text-align:left;"><code>BillingController</code> &lt;- <code>billingService.ts</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/billing/agencies/{id}/credits/summary &amp; /api/v1/agencies/{id}/credit/workspaces &amp; PUT /{wid}/limit</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>CreditBalanceController</code> &amp; <code>WorkspaceCreditController</code> &lt;- <code>creditService.ts</code></td></tr><tr><td style="text-align:left;"><code>GET /api/v1/billing/agencies/{id}/invoices/** &amp; /api/v1/admin/billing/invoices</code></td><td style="text-align:left;">Bearer (<code>Owner</code>, <code>Admin</code>)</td><td style="text-align:left;"><code>InvoiceHistoryController</code> &amp; <code>AdminInvoiceHistoryController</code> &lt;- <code>billingService.ts</code></td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Single-Device Mobile Banking Switch:</strong> User saves VietQR to gallery (<code>expo-media-library</code>) or copies transfer code, switches to banking app, and returns to BrandHub Mobile; <code>AppState</code> foreground listener immediately re-polls <code>GET /orders/{orderId}</code> (unlocking cleanly behind <code>AppLockGate</code> if <code>&gt; 60s</code>) and celebrates fulfillment.</li><li><strong><code>BIGINT</code> Precision on Mobile Hermes Engine:</strong> Credit and VND amounts parse safely from string/safe-integer DTOs (<code>planLimitHint.test.ts</code>).</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/08-subscription-billing/README.html">3.9 Subscription &amp; Billing</a> (<code>3.9.1–3.9.6</code>) · <a href="./../../../srs/09-admin-functions/README.html">FR 3.10.10–3.10.14 Admin Billing/Revenue</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/08-subscription-billing.html">BA 08 Subscription &amp; Billing</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
